/* ===== module: workout/preview-panels-ui.js ===== */
/* FORK: preview-panels UI — the DOM renderer for the pure core
   that shipped without a surface:

   #806 (user 2026-10-28): the former item 1, the PROGRAM page
   panel for the progression preview grid, is DELETED with the
   Progression preview section — the Program page no longer
   renders it, and its renderer, cell text and row context are
   gone from this module. The pure grid core remains in
   formulas/ with its own tests. Only the rep-max card below
   still lives here.

   EXERCISE page card for formulas/rep-max-table.js
      (forkRepMaxTable): for each rep count actually attempted, the
      best weight, the best estimated 1RM it produced, and the date
      of the best-weight set — every value under a column label, so
      no bare numbers.

   Shape of this module (mirrors the fork's pure-module pattern —
   originally workout/copy-last.js, removed in FORK v1.991.8/FR-49):
   the HTML
   builders are pure string functions of the CORES' OUTPUTS plus an
   options bag — unit-tested without a DOM — and the mount functions
   are the thin DOM edge (host lookup + innerHTML + the experiment
   gate). Nothing here computes a target or a best: all arithmetic
   stays in the cores. Display formatting rides the app's own
   globals when they exist (escapeHtml, displayWeight, weightUnit —
   all read at CALL time, so load order only needs this file after
   lib/utilities.js and formulas/units.js); standalone fallbacks keep
   the builders total when those globals are absent (unit tests).

   Options bag (the rep-max builder):
     unit         display unit string ('lb'/'kg'); default weightUnit()
                  when available, else 'lb'.
     formatWeight fn(canonicalLb) -> display string for a weight;
                  default displayWeight() when available (canonical
                  lb -> display conversion + metric rounding), else
                  the plain number. Dumbbell exercises: the caller may
                  pass a dbDisplayWeight-bound formatter (see the
                  integration note) — the cores speak canonical totals.
     formatE1RM   fn(canonicalLb) -> display string for an estimated
                  1RM; default: round to a whole unit, then formatWeight.
     formatDate   fn(dateString) -> display string for a rep-max row
                  date; default: the string as supplied. Pass NOTHING
                  when the logs came from getExerciseLogs() — its
                  `date` is already formatLogDate() output. Pass
                  formatLogDate only for raw ISO-dated log objects.
     exerciseName (rep-max card only) the exercise's display name for
                  the card's accessible label.

   The rep-max card is PERMANENT (it graduated with the
   experiments framework's removal, user ruling 2026-10-23): its
   mount below runs unconditionally.

   Data contract (full detail in the integration note): the mount
   below takes the core's output directly (forkRenderRepMaxCard
   takes the rows array). The forkMount* convenience wrapper calls
   the core itself when the coordinator prefers to hand over raw
   inputs. */

/* Standalone escaper (mirrors lib/utilities.js escapeHtml, quotes
   included) used only when the app global is absent. */
function forkPanelEscapeHtml(text) {
  return String(text == null ? '' : text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/* The app's escaper when loaded, else the fallback above. */
function forkPanelEsc(text) {
  return typeof escapeHtml === 'function' ? escapeHtml(text) : forkPanelEscapeHtml(text);
}

/* Strict numeric read, same rule as the grid core: booleans, '' and
   non-finite values are not numbers. */
function forkPanelNum(value) {
  if (value == null || value === '' || typeof value === 'boolean') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function forkPanelUnit(opts) {
  if (opts && typeof opts.unit === 'string' && opts.unit) return opts.unit;
  return typeof weightUnit === 'function' ? weightUnit() : 'lb';
}

/* Canonical-lb -> display string via the caller's formatter, else the
   app's displayWeight (unit conversion), else the raw number trimmed
   the way the grid core trims (integers stay integers, steps keep at
   most 3 decimals). */
function forkPanelFormatWeight(value, opts) {
  const n = forkPanelNum(value);
  if (n == null) return '';
  if (opts && typeof opts.formatWeight === 'function') return String(opts.formatWeight(n));
  if (typeof displayWeight === 'function') return displayWeight(n);
  return String(Math.round(n * 1000) / 1000);
}

/* Estimated 1RM display: the detail page's own e1RM labels round to a
   whole unit; the default here does the same before unit formatting. */
function forkPanelFormatE1RM(value, opts) {
  const n = forkPanelNum(value);
  if (n == null) return '';
  if (opts && typeof opts.formatE1RM === 'function') return String(opts.formatE1RM(n));
  return forkPanelFormatWeight(Math.round(n), opts);
}

function forkPanelFormatDate(value, opts) {
  if (value == null || value === '') return '';
  if (opts && typeof opts.formatDate === 'function') return String(opts.formatDate(value) || '');
  return String(value);
}

/* The EXERCISE-page rep-max card: pure builder over forkRepMaxTable's
   rows ([{reps, bestWeight, bestE1RM, date}], reps ascending — the
   builder re-sorts defensively and drops rows with no real reps or
   weight, so a hand-built array cannot smuggle in an invented row).
   FORK v1.991.20 (Round 12): the card is a real TABLE — one quiet
   header row (Reps / Best weight / Est. 1RM / Date; the header name
   settles here as "Est. 1RM") over aligned data rows with tabular
   numerals and hairline separators. The previous shape repeated a
   small label over every value in every row (a loose 4-up stack,
   and the date wrapped to a second line). A row with no estimate
   or no date keeps its cell, empty — the columns never shift.
   When the caller supplies the exercise's CURRENT estimate
   (opts.currentEst, canonical) and it differs from the lifetime
   best (opts.projected), it rides as the card's summary line above
   the table: the table's Est. 1RM column is the record per rep
   count, the summary line is what the latest session supports
   (#376 — the two numbers together are the honest picture).
   Empty input renders an honest empty line inside the card (the
   exercise simply has no weighted sets yet), not a header over
   nothing.
   FORK v1.997.37 (#696, user 2026-10-23: the table read "pretty
   clunky"): the presentation is the app's list-row language now —
   the header is a quiet column-label line and each rep count is
   one comfortable list row (taller padding, hairline separation,
   the shared column template from FR-220/FR-236 kept so every
   value still sits under its label; the two numeric columns are
   right-aligned tabular figures, the estimate column in the
   quieter row-meta tone so the logged best weight reads first).
   Data and math are untouched: same rows, same values, same
   estimate formula (formulas/rep-max-table.js). */
function forkRepMaxCardHtml(rows, opts) {
  const esc = forkPanelEsc;
  const unit = forkPanelUnit(opts);
  const list = (Array.isArray(rows) ? rows : [])
    .filter(r => r && forkPanelNum(r.reps) > 0 && forkPanelNum(r.bestWeight) > 0)
    .slice()
    .sort((a, b) => forkPanelNum(a.reps) - forkPanelNum(b.reps));
  const title = opts && typeof opts.title === 'string' && opts.title ? opts.title : 'Rep maxes';
  const aria = opts && typeof opts.exerciseName === 'string' && opts.exerciseName
    ? title + ' for ' + opts.exerciseName : title;
  const cur = forkPanelNum(opts && opts.currentEst);
  const best = forkPanelNum(opts && opts.projected);
  /* FORK v1.992.18 (P2-3, fix-list #7 residue): the line now names its
     basis. R7 (v1.991.67) labelled the page headline's basis ("From
     heaviest set") but this line — the latest session's best estimate
     (statsFor.currentEst) — still printed bare, so it read as a second,
     conflicting "current" 1RM and could sit below a heavier logged
     single with nothing saying why. The basis words are the
     explanation: it is the latest session only, where the headline is
     the heaviest set ever. */
  const currentLine = (list.length && cur != null && cur > 0 && best != null && Math.round(cur) !== Math.round(best))
    ? '<p class="fork-repmax-current">Current est. 1RM <strong>' + esc(forkPanelFormatE1RM(cur, opts)) + ' ' + esc(unit) + '</strong> (from your latest session)</p>'
    : '';
  const body = !list.length
    ? '<p class="section-note fork-repmax-empty">No weighted sets logged for this exercise yet. Rep maxes appear here after the first weighted session.</p>'
    : '<div class="fork-repmax-table" role="table" aria-label="' + esc(aria) + '">'
      + '<div class="fork-repmax-head"><span>Reps</span><span>Best weight</span><span>Est. 1RM</span><span>Date</span></div>'
      + list.map(r => {
        const e1 = forkPanelNum(r.bestE1RM);
        const date = forkPanelFormatDate(r.date, opts);
        return '<div class="fork-repmax-row">'
          + '<span class="fork-repmax-reps">' + esc(String(forkPanelNum(r.reps))) + '</span>'
          + '<span class="fork-repmax-num fork-repmax-weight">' + esc(forkPanelFormatWeight(r.bestWeight, opts)) + ' ' + esc(unit) + '</span>'
          + '<span class="fork-repmax-num fork-repmax-e1rm">' + (e1 != null && e1 > 0 ? esc(forkPanelFormatE1RM(r.bestE1RM, opts)) + ' ' + esc(unit) : '') + '</span>'
          + '<span class="fork-repmax-date">' + (date ? esc(date) : '') + '</span>'
          + '</div>';
      }).join('')
      + '</div>';
  /* #689: the three 1RM figures on the page stay — each already names
     its basis (#376 / P2-3 / B7). What the table never said was the
     estimate's cap: effective reps (reps + reps in reserve) count at
     most 15 (formulas/rep-max-table.js), so 185 × 20 reads 278, not
     Epley's 308. A row whose estimate sits exactly on the cap (bestE1RM
     = 1.5 × its weight) carries a marker and the card says why once,
     under the table; uncapped tables print nothing extra. */
  const capped = list.some(r => { const w = forkPanelNum(r.bestWeight), e = forkPanelNum(r.bestE1RM); return w > 0 && e > 0 && Math.abs(e / w - 1.5) < 1e-6; });
  const capNote = capped ? '<p class="fork-repmax-capnote">High-rep estimates count at most 15 reps, including reps left in reserve.</p>' : '';
  return '<section class="dashboard-card fork-repmax-card" aria-label="' + esc(aria) + '">'
    + '<div class="section-head"><div><h2>' + esc(title) + '</h2></div></div>'
    /* FORK v1.991.11 (bloat sweep): the subtitle's first sentence was
       cut — it restated the card's own column labels (Best weight /
       Best est. 1RM / reps).
       FORK v1.991.31 (FR-103, round 15): the remaining subtitle
       ("Warm-up sets do not count.") is DELETED on the user's direct
       word — he crossed it out in his screenshot; only the caption
       went at the time, so the card head is the title alone.
       FORK v1.992.21 (P2-7, D7 — the later ruling governs): the
       exclusion itself is now removed too. Warm-up sets count in
       this table exactly as they count in Stats (one rule, fix-list
       S3 #22), so no counting caption belongs here either. */
    + currentLine + body + capNote + '</section>';
}

/* --- Thin DOM mounts (the only DOM in this module) ---------------- */

function forkPanelMount(host, html) {
  if (!host || typeof host !== 'object') return false;
  host.innerHTML = html;
  return true;
}

/* Mount the rep-max card from READY rows (forkRepMaxTable output).
   The rep-max card is permanent since the experiments graduation
   (user ruling 2026-10-23). */
function forkRenderRepMaxCard(host, rows, opts) {
  return forkPanelMount(host, forkRepMaxCardHtml(rows, opts));
}

/* Convenience wrapper: one exercise's logs in, card mounted. Calls
   the rep-max core when it is loaded. NOTE: `logs` must already be
   ONE exercise's logs — getExerciseLogs(exerciseId) output, whose
   sets carry {w, r, tags} and whose `date` is display-formatted.
   FORK v1.992.21 (P2-7, D7): the core applies no warm-up filter
   (warm-ups count, as in Stats), so no `set.warmup` translation is
   needed from callers; the exercise page drops incomplete sets
   before handing logs over. */
function forkMountRepMaxCard(host, logs, opts) {
  if (typeof forkRepMaxTable !== 'function') return false;
  return forkRenderRepMaxCard(host, forkRepMaxTable(logs), opts);
}
